<?php require_once __DIR__.'/backend/helpers.php'; require_once __DIR__.'/backend/csrf.php'; $token=(string)($_GET['token']??''); ?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reset Password | Oh My Gracious</title><link rel="stylesheet" href="css/style.css"></head><body class="auth-body"><main class="simple-auth-card"><a class="brand-mark dark" href="index.html">OH MY GRACIOUS</a><h1>Create a new password</h1><div id="message" class="alert hidden"></div><label>New Password</label><input id="password" type="password"><label>Confirm Password</label><input id="confirm" type="password"><button id="save" class="btn primary full">Update Password</button></main><script>document.getElementById('save').onclick=async()=>{const fd=new FormData();fd.append('csrf_token','<?= h(csrfToken()) ?>');fd.append('token','<?= h($token) ?>');fd.append('password',document.getElementById('password').value);fd.append('confirm_password',document.getElementById('confirm').value);const r=await fetch('backend/reset-password.php',{method:'POST',body:fd});const d=await r.json();const m=document.getElementById('message');m.className='alert '+d.status;m.textContent=d.message;if(d.status==='success')setTimeout(()=>location.href='login.html',1200);};</script></body></html>
